以下是一个使用C#解析XML文件的示例代码，包含三种常用方法（XmlDocument、XmlReader和LINQ to XML）：

```csharp
using System;
using System.Xml;
using System.Xml.Linq;

class XmlParserExample
{
    static void Main()
    {
        string xmlPath = "books.xml";

        // 先创建示例XML文件
        CreateSampleXml(xmlPath);

        Console.WriteLine("使用XmlDocument解析:");
        ParseWithXmlDocument(xmlPath);

        Console.WriteLine("\n使用XmlReader解析:");
        ParseWithXmlReader(xmlPath);

        Console.WriteLine("\n使用LINQ to XML解析:");
        ParseWithLinqToXml(xmlPath);
    }

    static void CreateSampleXml(string path)
    {
        XDocument doc = new XDocument(
            new XElement("Books",
                new XElement("Book",
                    new XAttribute("id", "1"),
                    new XElement("Title", "C#入门经典"),
                    new XElement("Author", "John Sharp"),
                    new XElement("Price", "45.00")
                ),
                new XElement("Book",
                    new XAttribute("id", "2"),
                    new XElement("Title", ".NET设计模式"),
                    new XElement("Author", "Jane Doe"),
                    new XElement("Price", "60.50")
                )
            )
        );
        doc.Save(path);
    }

    static void ParseWithXmlDocument(string path)
    {
        XmlDocument doc = new XmlDocument();
        doc.Load(path);

        XmlNodeList books = doc.SelectNodes("/Books/Book");
        foreach (XmlNode book in books)
        {
            string id = book.Attributes["id"].Value;
            string title = book.SelectSingleNode("Title").InnerText;
            string author = book.SelectSingleNode("Author").InnerText;
            string price = book.SelectSingleNode("Price").InnerText;

            Console.WriteLine($"ID: {id}");
            Console.WriteLine($"标题: {title}");
            Console.WriteLine($"作者: {author}");
            Console.WriteLine($"价格: {price}\n");
        }
    }

    static void ParseWithXmlReader(string path)
    {
        using (XmlReader reader = XmlReader.Create(path))
        {
            while (reader.Read())
            {
                if (reader.NodeType == XmlNodeType.Element && reader.Name == "Book")
                {
                    string id = reader.GetAttribute("id");
                    string title = "";
                    string author = "";
                    string price = "";

                    while (reader.Read())
                    {
                        if (reader.NodeType == XmlNodeType.Element)
                        {
                            switch (reader.Name)
                            {
                                case "Title":
                                    title = reader.ReadElementContentAsString();
                                    break;
                                case "Author":
                                    author = reader.ReadElementContentAsString();
                                    break;
                                case "Price":
                                    price = reader.ReadElementContentAsString();
                                    break;
                            }
                        }

                        if (reader.NodeType == XmlNodeType.EndElement && reader.Name == "Book")
                            break;
                    }

                    Console.WriteLine($"ID: {id}");
                    Console.WriteLine($"标题: {title}");
                    Console.WriteLine($"作者: {author}");
                    Console.WriteLine($"价格: {price}\n");
                }
            }
        }
    }

    static void ParseWithLinqToXml(string path)
    {
        XDocument doc = XDocument.Load(path);
        var books = doc.Descendants("Book");

        foreach (var book in books)
        {
            string id = book.Attribute("id").Value;
            string title = book.Element("Title").Value;
            string author = book.Element("Author").Value;
            string price = book.Element("Price").Value;

            Console.WriteLine($"ID: {id}");
            Console.WriteLine($"标题: {title}");
            Console.WriteLine($"作者: {author}");
            Console.WriteLine($"价格: {price}\n");
        }
    }
}
```

**代码说明：**

1. **创建示例XML文件**：`CreateSampleXml` 方法使用LINQ to XML生成示例数据并保存为books.xml

2. **三种解析方法**：
   - **XmlDocument**：基于DOM的解析方式，适合小型XML文档
   - **XmlReader**：基于流的读取方式，适合处理大型XML文件
   - **LINQ to XML**：现代API，语法简洁，推荐用于新项目

3. **生成的XML结构**：
```xml
<Books>
  <Book id="1">
    <Title>C#入门经典</Title>
    <Author>John Sharp</Author>
    <Price>45.00</Price>
  </Book>
  <Book id="2">
    <Title>.NET设计模式</Title>
    <Author>Jane Doe</Author>
    <Price>60.50</Price>
  </Book>
</Books>
```

**使用方法：**
1. 创建C#控制台项目
2. 添加System.Xml和System.Xml.Linq的引用
3. 将代码复制到Program.cs
4. 运行程序后会在bin目录生成books.xml文件

**各方法比较：**
- **XmlDocument**：内存占用较高，但操作方便
- **XmlReader**：内存效率高，但代码较复杂
- **LINQ to XML**：API友好，代码简洁，推荐使用

实际开发中建议：
- 小文件优先使用LINQ to XML
- 大文件使用XmlReader
- 需要修改XML结构时可以考虑XmlDocument

