### **2. 注册命令**
在 `plugin.yml` 中注册命令：
```yaml
commands:
  fixlight:
    description: 修复选区内的光照
    usage: /fixlight
```

---

### **3. 主命令逻辑**
创建命令执行类 `FixLightCommand.java`：

```java
import com.sk89q.worldedit.bukkit.WorldEditPlugin;
import com.sk89q.worldedit.regions.Region;
import org.bukkit.Bukkit;
import org.bukkit.Chunk;
import org.bukkit.command.Command;
import org.bukkit.command.CommandExecutor;
import org.bukkit.command.CommandSender;
import org.bukkit.entity.Player;

public class FixLightCommand implements CommandExecutor {

    @Override
    public boolean onCommand(CommandSender sender, Command cmd, String label, String[] args) {
        if (!(sender instanceof Player)) {
            sender.sendMessage("只有玩家可以使用此命令！");
            return true;
        }

        Player player = (Player) sender;
        WorldEditPlugin wePlugin = (WorldEditPlugin) Bukkit.getPluginManager().getPlugin("WorldEdit");
        if (wePlugin == null) {
            player.sendMessage("§c需要安装WorldEdit插件！");
            return true;
        }

        try {
            // 获取WorldEdit选区和区域
            com.sk89q.worldedit.LocalSession session = wePlugin.getSession(player);
            Region region = session.getSelection(session.getSelectionWorld());
            if (region == null) {
                player.sendMessage("§c请先用WorldEdit选择一个区域！");
                return true;
            }

            // 创建EditSession并修复光照
            try (com.sk89q.worldedit.EditSession editSession = wePlugin.createEditSession(player)) {
                editSession.setMask(null);
                editSession.enableQueue();
                editSession.fixLighting(region); // 关键方法
                editSession.flushQueue();
            }

            // 刷新所有受影响的区块
            for (Chunk chunk : getChunksInRegion(region, player.getWorld())) {
                chunk.getWorld().refreshChunk(chunk.getX(), chunk.getZ());
            }

            player.sendMessage("§a光照修复完成！");
        } catch (Exception e) {
            player.sendMessage("§c发生错误：" + e.getMessage());
            e.printStackTrace();
        }
        return true;
    }

    // 获取区域内的所有区块
    private Chunk[] getChunksInRegion(Region region, org.bukkit.World bukkitWorld) {
        Set<Chunk> chunks = new HashSet<>();
        for (com.sk89q.worldedit.BlockVector3 pt : region) {
            int chunkX = pt.getBlockX() >> 4;
            int chunkZ = pt.getBlockZ() >> 4;
            chunks.add(bukkitWorld.getChunkAt(chunkX, chunkZ));
        }
        return chunks.toArray(new Chunk[0]);
    }
}
```

---

### **4. 插件主类注册**
在插件主类中注册命令：
```java
