    descriptors{i} = extractHOGFeatures(neighborhood);
end
```

### 2. 相似度计算
使用余弦相似度进行比对：
```matlab
function score = matchFingerprints(desc1, desc2)
    numPairs = 0;
    totalScore = 0;
    for i = 1:length(desc1)
        for j = 1:length(desc2)
            similarity = dot(desc1{i}, desc2{j})/(norm(desc1{i})*norm(desc2{j}));
            if similarity > 0.7
                totalScore = totalScore + similarity;
                numPairs = numPairs + 1;
            end
        end
    end
    score = totalScore / max(numPairs, 1);
end
```

