    <div class="controls">
      <input v-model="inputText" placeholder="输入文字" />
      <button @click="addTextBlock">添加</button>
    </div>

    <!-- 文字块容器 -->
    <div class="text-container">
      <div 
        v-for="(block, index) in textBlocks"
        :key="block.id"
        class="text-block"
        :style="{
          left: block.x + 'px',
          top: block.y + 'px'
        }"
        @mousedown="startDrag(index, $event)"
      >
        {{ block.text }}
        <button 
          class="delete-btn"
          @click.stop="deleteTextBlock(index)"
        >×</button>
      </div>
    </div>
  </div>
</template>

<script>
export default {
  data() {
    return {
      inputText: '',
      textBlocks: [],
      draggingIndex: null,
      startX: 0,
      startY: 0,
      initialX: 0,
      initialY: 0
    }
  },
  methods: {
    addTextBlock() {
      if (!this.inputText.trim()) return
      this.textBlocks.push({
        id: Date.now(),
        text: this.inputText,
        x: 50,  // 初始位置
        y: 50
      })
      this.inputText = ''
    },

    deleteTextBlock(index) {
      this.textBlocks.splice(index, 1)
    },

    startDrag(index, e) {
      this.draggingIndex = index
      this.startX = e.clientX
      this.startY = e.clientY
      this.initialX = this.textBlocks[index].x
      this.initialY = this.textBlocks[index].y

      document.addEventListener('mousemove', this.handleDrag)
      document.addEventListener('mouseup', this.stopDrag)
    },

    handleDrag(e) {
      if (this.draggingIndex === null) return

      const dx = e.clientX - this.startX
      const dy = e.clientY - this.startY

      this.textBlocks[this.draggingIndex].x = this.initialX + dx
      this.textBlocks[this.draggingIndex].y = this.initialY + dy
    },

    stopDrag() {
      this.draggingIndex = null
      document.removeEventListener('mousemove', this.handleDrag)
      document.removeEventListener('mouseup', this.stopDrag)
    }
  }
}
</script>

